export function getNativeTabProperties({ extension, tabProperties }) {
  const userContextId = tabProperties.cookieStoreId
    ? ExtensionParent.apiManager.global.getUserContextIdForCookieStoreId(
        extension,
        tabProperties.cookieStoreId
      )
    : Services.scriptSecurityManager.DEFAULT_USER_CONTEXT_ID;

// Open space #1.
await openSpace(space_1, url1);
// Verify cookieStoreIds.
const [spaceTab1] = await browser.tabs.query({ spaceId: space_1.id });
browser.test.assertEq(
  "firefox-default",
  spaceTab1.cookieStoreId,
  `The cookieStoreId for space_1 should be correct.`
);
// Verify tab properties.
await window.sendMessage("checkTabs", {
  spaceName: "space_1",
  openSpacesUrls: [url1],
});

// Open space #2.
await openSpace(space_2, url2);
// Verify cookieStoreIds.
const [spaceTab2] = await browser.tabs.query({ spaceId: space_2.id });
browser.test.assertEq(
  "firefox-container-1",
  spaceTab2.cookieStoreId,
  `The cookieStoreId for space_2 should be correct.`

add_task(async function no_cookies_permission() {
  await SpecialPowers.pushPrefEnv({
    set: [["privacy.userContext.enabled", true]],
  });

  const extension = ExtensionTestUtils.loadExtension({
    async background() {
      await browser.test.assertRejects(
        browser.windows.create({
          type: "popup",
          cookieStoreId: "firefox-container-1",
        }),
        /No permission for cookieStoreId/,
        "cookieStoreId requires cookies permission"
      );
